/*---
description: el locale casing expands precomposed ypogegrammeni when uppercasing
features: [ts-unicode-locale-case, ts-unicode-sequences, ts-strings]
---*/
// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
const input = "\u1fb3";
const lower = input.toLocaleLowerCase("\u0065\u006c");
const upper = input.toLocaleUpperCase("\u0065\u006c");
assert.sameValue(lower, "\u1fb3");
assert.sameValue(lower.length, 1);
assert.sameValue(upper, "\u0391\u0399");
assert.sameValue(upper.length, 2);
